    counts = Counter(cells)
    bg_color = max(counts.items(), key=lambda x: x[1])[0]
    fg_color = [c for c in counts.keys() if c != bg_color][0]

    # Find bounding box of foreground
    fg_rows = set()
    fg_cols = set()
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == fg_color:
                fg_rows.add(i)
                fg_cols.add(j)

    # Map sorted indices to output coordinates
    sorted_rows = sorted(fg_rows)
    sorted_cols = sorted(fg_cols)

    # Output size = bounding box size * 2 (scaled)
    out_h = len(sorted_rows) * 2 if sorted_rows else 1
    out_w = len(sorted_cols) * 2 if sorted_cols else 1

    output = [['=' for _ in range(out_w)] for _ in range(out_h)]

    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == fg_color:
                r_pos = sorted_rows.index(i)
                c_pos = sorted_cols.index(j)
                out_i = r_pos * 2
                out_j = c_pos * 2

                # Write 2x2 block
                for dr in range(2):
                    for dc in range(2):
                        if out_i + dr < out_h and out_j + dc < out_w:
                            output[out_i + dr][out_j + dc] = fg_color

    return output
